package main

import &quot;fmt&quot;

func Unique[T comparable] (ts ...T) []T {
	var (
		seen = make(map[T]struct{})
		result []T
	)
	for _, t := range ts {
		if _, ok := seen[t]; !ok {
			seen[t] = struct{}{}
			result = append(result, t)
		}
	}
	return result
}

type User struct {
	ID  int
}

type NoCmpUser struct {
	ID  int

	noCmp [0]func() &#47;&#47; This field is used to prevent the type from being comparable
}

func main() {
	fmt.Println(Unique(1,1,2,2,3,4,6,7,8))
	fmt.Println(Unique(&quot;a&quot;, &quot;b&quot;, &quot;c&quot;, &quot;a&quot;, &quot;b&quot;, &quot;d&quot;))
	fmt.Println(Unique(User{ID: 1}, User{ID: 2}, User{ID: 1}, User{ID: 3}))
	&#47;&#47; fmt.Println(Unique(NoCmpUser{ID: 1}, NoCmpUser{ID: 2}, NoCmpUser{ID: 1}, NoCmpUser{ID: 3})) &#47;&#47; This will not compile because NoCmpUser is not comparable
}
